namespace RonSijm.FluidHumidifier.Factories.Glue;

public class ConnectionTypeFactory(string resourceName = null, Action<Humidifier.Glue.ConnectionType> factoryAction = null) : ResourceFactory<Humidifier.Glue.ConnectionType>(resourceName)
{

    internal InnerConnectionTypeConnectorAuthenticationConfigurationFactory ConnectorAuthenticationConfigurationFactory { get; set; }

    internal InnerConnectionTypeConnectionPropertiesConfigurationFactory ConnectionPropertiesFactory { get; set; }

    internal InnerConnectionTypeRestConfigurationFactory RestConfigurationFactory { get; set; }

    protected override Humidifier.Glue.ConnectionType Create()
    {
        var connectionTypeResult = CreateConnectionType();
        factoryAction?.Invoke(connectionTypeResult);

        return connectionTypeResult;
    }

    private Humidifier.Glue.ConnectionType CreateConnectionType()
    {
        var connectionTypeResult = new Humidifier.Glue.ConnectionType
        {
            GivenName = InputResourceName,
        };

        return connectionTypeResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionType result)
    {
        base.CreateChildren(result);

        result.ConnectorAuthenticationConfiguration ??= ConnectorAuthenticationConfigurationFactory?.Build();
        result.ConnectionProperties ??= ConnectionPropertiesFactory?.Build();
        result.RestConfiguration ??= RestConfigurationFactory?.Build();
    }

} // End Of Class

